: 156 байт, распределяемые каждую секунду
Сетевые пакеты
: 1024 байт, распределяемые каждые 5 секунд
Конфигурация
: 2048 байт, распределяемые при запуске
Временные буферы
: 256 байт, распределяемые во время обработки
Предсказуемые размеры, предсказуемый срок жизни.
Мне не нужен был общий распределитель, достаточно было
специализированных распределителей
для каждого сценария.
Стратегия 1: пулы памяти фиксированного размера
Для данных датчиков (156 байт, распределяемые каждую секунду), я создал пул фиксированного размера:
#define SENSOR_POOL_SIZE 256 // Округляется вверх до степени двойки
#define SENSOR_POOL_COUNT 10 // Максимум десять одновременных показаний

typedef struct free_block {
 struct free_block *next;
} free_block_t;

typedef struct {
 uint8_t memory[SENSOR_POOL_SIZE * SENSOR_POOL_COUNT];
 free_block_t *free_list;
} sensor_pool_t;

static sensor_pool_t g_sensor_pool;

void sensor_pool_init(void) {
 g_sensor_pool.free_list = NULL;

 // Связываем все блоки в список для освобождения
 for (int i = 0; i < SENSOR_POOL_COUNT; i++) {
 free_block_t *block = (free_block_t *)&g_sensor_pool.memory[i * SENSOR_POOL_SIZE];
 block->next = g_sensor_pool.free_list;
 g_sensor_pool.free_list = block;
 }
}

void *sensor_alloc(void) {
 if (!g_sensor_pool.free_list) {
 return NULL; // Пул исчерпан
 }

 void *ptr = g_sensor_pool.free_list;
 g_sensor_pool.free_list = g_sensor_pool.free_list->next;
 return ptr;
}

void sensor_free(void *ptr) {
 free_block_t *block = (free_block_t *)ptr;
 block->next = g_sensor_pool.free_list;
 g_sensor_pool.free_list = block;
}
