 if (size <= 32) {
 return pool_alloc(&g_pools.small_pool);
 } else if (size <= 256) {
 return pool_alloc(&g_pools.medium_pool);
 } else if (size <= 4096) {
 return pool_alloc(&g_pools.large_pool);
 } else {
