public class ViewModel {
	private readonly AsyncDelegateCommand _startFindDevicesCommand;
	private readonly DelegateCommand _cancelFindDevicesCommand;

	private readonly ObservableCollection<DeviceModbus> _connectedDevices = new();

	private readonly FindDevicesService _findDevicesService = new();

	private CancellationTokenSource? _findDevicesCTS;

	public ViewModel() {
 _startFindDevicesCommand = new AsyncDelegateCommand(StartFindDevicesAsync);
 _cancelFindDevicesCommand = new DelegateCommand(CancelFindDevices);
	}

	public AsyncDelegateCommand StartFindDevicesCommand => _startFindDevicesCommand;
	public DelegateCommand CancelFindDevicesCommand => _cancelFindDevicesCommand;

	public ObservableCollection<DeviceModbus> ConnectedDevices => _connectedDevices;

	/// <summary>
	/// Запуск процесса поиска устройств
	/// </summary>
	private async Task StartFindDevicesAsync() {
 if (null != _findDevicesCTS
 && !_findDevicesCTS.IsCancellationRequested) {
 // Выполняем какие-то действия, к примеру, говорим пользователю, что токен поиска устройств занят
 return;
 }

 _findDevicesCTS = new CancellationTokenSource();

 if (0 < ConnectedDevices.Count)
 ConnectedDevices.Clear();

 IAsyncEnumerable<DeviceModbus> sourceCollection = _findDevicesService.StartFindDevicesAsync(_findDevicesCTS.Token);
 await foreach (var foundDevice in sourceCollection) {
 ConnectedDevices.Add(foundDevice);
 }

 CancelFindDevices();
	}

	/// <summary>
	/// Остановка процесса поиска устройств
	/// </summary>
	private void CancelFindDevices() {
 if (null == _findDevicesCTS
 || _findDevicesCTS.IsCancellationRequested)
 return;

 _findDevicesCTS.Cancel();
	}
}
